// Code generator for the adapter icon registry.
//
// Reads the checked-in SVG sources under src/icons/ and inlines them into
// src/generated.ts as string constants plus a type -> AdapterIcon map. The
// generated file is committed so the package builds with plain `tsc` and needs
// no asset-copy step. Re-run with `pnpm --filter @mininglamp-oss/octo-harness-adapter-icons generate`
// after adding or updating an SVG.
//
// To add a provider: drop its SVG under src/icons/, add a row below, re-run.
import { readFileSync, writeFileSync, existsSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { dirname, join } from "node:path";

const here = dirname(fileURLToPath(import.meta.url));
const iconsDir = join(here, "..", "src", "icons");
const outFile = join(here, "..", "src", "generated.ts");

// Metadata keyed by adapter `type`. `monochrome` marks single-color glyphs the
// consumer should tint (currentColor / maskImage); `darkFile` is set only when
// a brand ships a dedicated dark-theme variant. Icons are sourced from LobeHub
// Icons (https://lobehub.com/icons) unless noted.
const ICONS = [
  { type: "codex", name: "Codex", file: "codex.svg", const: "codexIcon" },
  { type: "claude-code", name: "Claude Code", file: "claude-code.svg", const: "claudeCodeIcon" },
  { type: "codebuddy", name: "CodeBuddy", file: "codebuddy.svg", const: "codebuddyIcon" },
  { type: "hermes", name: "Hermes", file: "hermes.svg", monochrome: true, const: "hermesIcon" },
  { type: "kimi-code", name: "Kimi Code", file: "kimi-code.svg", const: "kimiCodeIcon" },
  { type: "mcode", name: "MiniMax Code", file: "mcode.svg", const: "mcodeIcon" },
  { type: "opencode", name: "OpenCode", file: "opencode.svg", monochrome: true, const: "opencodeIcon" },
  { type: "openclaw", name: "OpenClaw", file: "openclaw.svg", const: "openclawIcon" },
  { type: "qodercli", name: "Qoder", file: "qoder.svg", const: "qoderCliIcon" },
  { type: "qoderclicn", name: "Qoder CN", file: "qoderclicn.svg", const: "qoderCliCnIcon" },
  { type: "zcode-gui", name: "ZCode", file: "zcode.svg", monochrome: true, const: "zcodeGuiIcon" }
];

const read = (name) => readFileSync(join(iconsDir, name), "utf8").trim();

const present = [];
const missing = [];
for (const icon of ICONS) {
  if (existsSync(join(iconsDir, icon.file)) && (!icon.darkFile || existsSync(join(iconsDir, icon.darkFile)))) {
    present.push(icon);
  } else {
    missing.push(icon.type);
  }
}
if (missing.length > 0) {
  console.warn(`[generate-icons] skipping types with no SVG source: ${missing.join(", ")}`);
}

const lines = [];
lines.push("// AUTO-GENERATED by scripts/generate-icons.mjs — do not edit by hand.");
lines.push("// Re-run `pnpm --filter @mininglamp-oss/octo-harness-adapter-icons generate` after changing an SVG.");
lines.push('import type { AdapterIcon } from "./types.js";');
lines.push("");
for (const icon of present) {
  const fields = [
    `type: ${JSON.stringify(icon.type)}`,
    `name: ${JSON.stringify(icon.name)}`,
    ...(icon.monochrome ? ["monochrome: true"] : []),
    `svg: ${JSON.stringify(read(icon.file))}`,
    ...(icon.darkFile ? [`darkSvg: ${JSON.stringify(read(icon.darkFile))}`] : [])
  ];
  lines.push(`export const ${icon.const}: AdapterIcon = {`);
  for (const field of fields) lines.push(`  ${field},`);
  lines.push("};");
  lines.push("");
}
lines.push("/** All adapter icons keyed by adapter `type`. */");
lines.push("export const adapterIcons: ReadonlyMap<string, AdapterIcon> = new Map<string, AdapterIcon>([");
for (const icon of present) lines.push(`  [${JSON.stringify(icon.type)}, ${icon.const}],`);
lines.push("]);");
lines.push("");

writeFileSync(outFile, lines.join("\n"));
console.log(`[generate-icons] wrote ${present.length} icons to ${outFile}`);
